<template><Teleport to="body"><view v-if="drag" class="notebook-drag-layer" aria-live="polite"><SlideDropTarget :x="drag.targetX" :y="drag.targetY" :ready="drag.ready" :progress="proximity" :accepted="drag.phase==='accepted'" :mode="drag.notebook==='known'?'review':'known'"/><view :class="['notebook-drag-ghost',drag.phase]" :style="{width:width+'px',transform:'translate3d('+(drag.x-width/2)+'px,'+(drag.y-36)+'px,0)'}"><view class="notebook-drag-card"><text lang="fr">{{ drag.label }}</text><Icon name="book"/></view></view></view></Teleport></template>
<script setup>import {computed} from 'vue';import SlideDropTarget from './SlideDropTarget.vue';import Icon from './Icon.vue';const props=defineProps({drag:Object});const proximity=computed(()=>Math.max(0,1-Math.hypot((props.drag?.x||0)-(props.drag?.targetX||0),(props.drag?.y||0)-(props.drag?.targetY||0))/145));const width=computed(()=>Math.min(260,Math.max(160,props.drag?.rect?.width||220)));</script>
<style scoped>.notebook-drag-layer{position:fixed;inset:0;pointer-events:none;z-index:215}.notebook-drag-ghost{position:absolute;left:0;top:0;will-change:transform;opacity:1}.notebook-drag-card{display:flex;align-items:center;gap:12px;min-height:72px;padding:15px 18px;border-radius:19px;background:var(--theme-panel,#f8faff);border:1px solid #ffffffdd;box-shadow:0 12px 35px rgba(var(--theme-rgb),.22),0 2px 8px #3240570d;transform:scale(1.035);animation:notebook-lift .18s ease-out}.notebook-drag-card>text{flex:1;font:20px/1.5 Georgia,serif;color:var(--ink);overflow-wrap:anywhere}.notebook-drag-card>.icon{width:18px;height:18px;color:var(--accent)}.notebook-drag-ghost.accepted,.notebook-drag-ghost.returning{transition:transform .24s cubic-bezier(.2,.8,.3,1),opacity .24s}.notebook-drag-ghost.accepted{opacity:0;transition:transform .34s cubic-bezier(.3,.7,.4,1),opacity .34s}.notebook-drag-ghost.accepted .notebook-drag-card{transform:scale(.15);transition:transform .34s}.notebook-drag-ghost.returning{opacity:0}.notebook-drag-ghost.returning .notebook-drag-card{transform:scale(.97);transition:transform .24s}@keyframes notebook-lift{from{opacity:.5;transform:scale(.98)}to{opacity:1;transform:scale(1.035)}}@media(prefers-reduced-motion:reduce){.notebook-drag-ghost,.notebook-drag-card{animation:none!important;transition:none!important}}</style>
